-- Run once after schema.sql to import the existing public website content.
begin;
update public.events set gallery_urls=array['/assets/natgess/Image1.jpg','/assets/natgess/Image2.jpg','/assets/natgess/Image3.jpg'] where slug='gess-fest' and cardinality(gallery_urls)=0;
update public.events set gallery_urls=array['/assets/general_assembly/AllStudents(2026GeneralAssembly).jpg','/assets/general_assembly/GE2A.jpg','/assets/general_assembly/GE3A.jpg','/assets/general_assembly/GE4A.jpg','/assets/general_assembly/GE5A.jpg'] where slug='general-assembly' and cardinality(gallery_urls)=0;
commit;

